function spark(v,c){const a=v.filter(x=>x!=null),lo=Math.min(...a),up=Math.max(...a),W=170,H=44,x=i=>i*W/58,y=a=>H-4-(a-lo)/(up-lo||1)*(H-10);let d='',pen=false;v.forEach((a,i)=>{if(a==null){pen=false;return}d+=(pen?'L':'M')+x(i).toFixed(1)+' '+y(a).toFixed(1);pen=true});return `<svg viewBox="0 0 ${W} ${H}"><path d="${d}" fill="none" stroke="${c||'var(--r5)'}" stroke-width="2"/></svg>`}
function heat(rowsK,getv,pk){const L=132,W=820,rh=26,cw=(W-L)/59,H=rowsK.length*rh+30;let s=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Heatmap">`;rowsK.forEach((c,r)=>{s+=`<text x="${L-8}" y="${r*rh+17}" text-anchor="end">${esc(c)}</text>`;const v=getv(c);v.forEach((x,i)=>{const p=v[i-1];if(i==0||x==null||p==null)return;const d=x/p-1,a=Math.min(Math.abs(d)/.4,1)*.88+.1;s+=`<rect x="${L+i*cw}" y="${r*rh+2}" width="${cw-.6}" height="${rh-3}" fill="${d>=0?'var(--r4)':'var(--wn)'}" fill-opacity="${a.toFixed(2)}" ${tt(c+' '+fy(1966+i)+' · '+pc(d),pk(c,i))}/>`})});for(let i=0;i<59;i+=10)s+=`<text x="${L+i*cw}" y="${H-8}">${1966+i}</text>`;return s+'</svg>'}
