document.addEventListener('mousemove',e=>{const p=e.target.closest?.('[data-tt]'),t=$('tip');if(p){t.textContent=p.dataset.tt;t.style.display='block';t.style.left=Math.min(e.clientX+14,innerWidth-270)+'px';t.style.top=e.clientY+16+'px'}else t.style.display='none'});
