function evFor(q){const out=[];EV.forEach(e=>{let s=0,d=false;if(q.c&&(e.c.includes(q.c)||(GR.includes(q.c)&&e.c.some(x=>['Rice','Wheat','Maize'].includes(x)))))s+=2;if(q.y!=null){if(e.y.includes(q.y)){s+=4;d=true}else if(e.y.some(a=>Math.abs(a-q.y)==1))s+=1.2}if(q.p&&e.p.includes(q.p)){s+=3;d=true}if(q.t&&e.t==q.t)s+=1;if(s>=2.2)out.push({e,s,d})});return out.sort((a,b)=>b.s-a.s).slice(0,3)}
