const SK={K:'Kharif',R:'Rabi',S:'Summer'},mainS=c=>{const se=SE[c]||{};return Object.keys(se).sort((a,b)=>mean(se[b].A)-mean(se[a].A))[0]};
function sResid(c,s){const v=(SE[c]||{})[s]?.Y;if(!v)return null;const idx=v.map((x,i)=>x!=null&&x>0?i:null).filter(i=>i!=null);if(idx.length<30)return null;const f=ols(idx,idx.map(i=>v[i])),mu=mean(idx.map(i=>v[i]));return v.map((x,i)=>x!=null&&x>0?Math.max(-100,Math.min(100,(x-(f.a+f.b*i))/Math.max(f.a+f.b*i,.25*mu)*100)):null)}
