function corrN(a,b){const p=a.map((x,i)=>[x,b[i]]).filter(q=>q[0]!=null&&q[1]!=null);if(p.length<10)return null;const r=corr(p.map(q=>q[0]),p.map(q=>q[1]));return{r,n:p.length,t:r*Math.sqrt((p.length-2)/(1-r*r))}}
