function eventStudy(kind){const s=kind=='rain'?'K':'R',key=kind=='rain'?'Kharif_rain':'Rabi_temp',cv=X.sea[key],ok=cv.map((x,i)=>x!=null?i:null).filter(i=>i!=null),sorted=ok.slice().sort((a,b)=>kind=='rain'?cv[a]-cv[b]:cv[b]-cv[a]),k=Math.max(5,Math.round(ok.length*.2)),stress=new Set(sorted.slice(0,k));
return{stress:[...stress].sort((a,b)=>a-b),rows:CS.filter(c=>SE[c]&&SE[c][s]).map(c=>{const r=sResid(c,s);if(!r)return null;const a=[],b=[];r.forEach((x,i)=>{if(x==null||cv[i]==null)return;(stress.has(i)?a:b).push(x)});const w=welch(a,b);return w?{c,...w}:null}).filter(Boolean).sort((x,y)=>x.d-y.d)}}
