const HIG={overview:['यहाँ से शुरू करें: तीन शब्द काफ़ी हैं','**क्षेत्रफल** यानी कितनी ज़मीन में बुवाई हुई (हेक्टेयर में; एक हेक्टेयर लगभग 2.5 एकड़)। **उत्पादन** यानी कुल फ़सल (टन में)। **उपज** यानी प्रति हेक्टेयर फ़सल (किग्रा/हेक्टेयर)। उसी ज़मीन पर उपज बढ़े तो हर खेत ज़्यादा दे रहा है। किसी भी नक्शे, बार या चार्ट के बिंदु पर क्लिक करें, उस आँकड़े का सरल भाषा में मतलब और संबंधित लेख खुल जाएँगे।'],stories:['कहानियाँ एक-एक सवाल समझाती हैं','हर कहानी में तीन बातें अलग रखी गई हैं: आँकड़े क्या कहते हैं, अख़बारों, शोधकर्ताओं और सरकारी रिपोर्टों ने क्या कहा, और अभी क्या पता नहीं है। आप अपनी पसंद की फ़सल और जगह चुनकर ख़ुद की कहानी भी बनवा सकते हैं।'],atlas:['नक्शा कैसे पढ़ें','हर ज़िला चुनी हुई फ़सल की मात्रा के हिसाब से रंगा गया है। गहरा रंग यानी ज़्यादा। स्लेटी यानी उस ज़िले ने वह फ़सल दर्ज नहीं की। क्षेत्रफल (ज़मीन), उत्पादन (फ़सल) या उपज (प्रति हेक्टेयर फ़सल) चुनें। किसी ज़िले पर क्लिक करें तो उसकी रैंक और उसकी सबसे बड़ी फ़सलें दिखेंगी।'],districts:['ज़िले क्या उगाते हैं, यह कैसे देखें','**फ़सल विविधता** बताती है कि ज़िला कितनी अलग-अलग फ़सलों पर निर्भर है। **विशेषज्ञता** बताती है कि ज़िला किस फ़सल में असामान्य रूप से मज़बूत है। **खेती के प्रकार** मिलती-जुलती फ़सलों वाले ज़िलों को एक साथ रखते हैं। **उपज अंतर** बताता है कि कम उपज वाले ज़िले बेहतर स्तर पर पहुँचें तो कितनी फ़सल और मिल सकती है। ये तुलनाएँ हैं, अंक नहीं।'],explore:['एक फ़सल, साठ साल','जब हर हेक्टेयर से ज़्यादा फ़सल मिलती है तो रेखा ऊपर जाती है। किसी साल पर माउस ले जाएँ तो मान दिखेगा, क्लिक करें तो उस साल की व्याख्या खुलेगी। छोटे चार्ट सभी फ़सलों की झलक देते हैं। सुनहरे निशान बिहार के अपने सरकारी आँकड़े हैं (2020–21 से 2024–25); जहाँ ये राज्यव्यापी श्रृंखला से अलग हों, वहाँ बिहार के आँकड़े मान्य हैं।'],seasons:['बिहार की फ़सल-ऋतुएँ','फ़सलें तीन मुख्य ऋतुओं में उगती हैं। **ख़रीफ़** की बुवाई मानसून के साथ, **रबी** की सर्दियों में, और **गर्मा** बीच में होती है। बिहार के ज़िला रिकॉर्ड में चार नाम हैं: **अगहनी** (मुख्य ख़रीफ़, यानी जाड़े का धान), **भदई** (शुरुआती ख़रीफ़), **गर्मा** (गर्मी) और **रबी**। फ़सल चुनकर देखें कि वह किस ऋतु में उगती है और समय के साथ कैसे बदली।'],structure:['कब और क्यों बदला','यह पन्ना तीन सवाल पूछता है। **उपज कब तेज़ी से बढ़ने लगी?** **क्या किसान अनाज, दलहन और तिलहन के बीच बदले?** **फ़सल इसलिए बढ़ी कि ज़्यादा ज़मीन बोई गई, या इसलिए कि हर हेक्टेयर ने ज़्यादा दिया?** जवाब पैटर्न बताते हैं, कारण साबित नहीं करते।'],climate:['मौसम का फ़सल पर असर','सही समय पर बारिश और ग़लत समय पर गर्मी फ़सल घटा सकती है। यहाँ बारिश और तापमान को उपज के साथ रखा गया है। साल भर की कुल बारिश समय का हाल छुपा देती है, इसलिए यहाँ ख़रीफ़ और रबी के हिसाब से भी जाँच है।'],bench:['बिहार की दूसरे राज्यों से तुलना','लंबी पट्टी यानी उस फ़सल का ज़्यादा मान। राज्यों की मिट्टी, जलवायु और खेती के तरीक़े अलग हैं, इसलिए छोटी पट्टी का मतलब हमेशा कमज़ोर खेती नहीं है। पाँच साल की वृद्धि तालिका बताती है कि कौन-से राज्य तेज़ी से बढ़े।'],compare:['दो चीज़ें साथ-साथ','दो फ़सलें या दो ज़िले चुनें। फ़सलों में दोनों रेखाएँ उस पहले साल से 100 पर शुरू होती हैं जिसमें दोनों के आँकड़े हैं, ताकि पता चले किसकी बढ़त ज़्यादा रही। ज़िलों में पट्टियाँ दिखाती हैं कि हर फ़सल को कितनी ज़मीन मिली।'],learn:['हर शब्द का सरल मतलब','इस साइट के सारे आँकड़े नीचे दिए शब्दों से समझे जा सकते हैं। जो शब्द मिले, उसका मतलब यहीं पढ़ लें।']};
const GLH=[['हेक्टेयर (ha)','ज़मीन की माप: 10,000 वर्ग मीटर, लगभग 2.5 एकड़।'],['क्षेत्रफल','किसी मौसम में फ़सल के लिए बोई गई ज़मीन (हेक्टेयर में)। एक ज़िले में एक फ़सल कई मौसमों में भी हो सकती है।'],['उत्पादन','कुल फ़सल, टन में (1 टन = 10 क्विंटल = 1,000 किग्रा)।'],['उपज','उत्पादन ÷ क्षेत्रफल, किग्रा प्रति हेक्टेयर। ज़मीन कितनी उपजाऊ है, इसका सबसे अच्छा एक माप।'],['ख़रीफ़, रबी, गर्मा','ख़रीफ़ की बुवाई मानसून (जून–जुलाई) में होती है और कटाई शरद में, जैसे धान। रबी की बुवाई सर्दियों में और कटाई वसंत में, जैसे गेहूँ। गर्मा इनके बीच की फ़सलें हैं।'],['वित्त-वर्ष का नाम','इस साइट पर 2022–23 को 2022 लिखा गया है। 2022 की ख़रीफ़ और 2023 के वसंत में कटी रबी, दोनों इसी वर्ष में आती हैं।'],['अग्रिम अनुमान','किसी साल की फ़सल का शुरुआती सरकारी अनुमान, जो बाद में बदल सकता है। यहाँ का आख़िरी साल तीसरा अग्रिम अनुमान है।'],['एमएसपी','न्यूनतम समर्थन मूल्य: वह कीमत जिस पर सरकार कुछ फ़सलें ख़रीदने को प्रतिबद्ध है। “नॉमिनल” यानी महँगाई के हिसाब से न बदला हुआ।'],['एपीवाई','क्षेत्रफल, उत्पादन, उपज: ज़िले की मानक आँकड़ा तालिका।'],['कोरोप्लेथ नक्शा','ऐसा नक्शा जिसमें हर क्षेत्र मान के हिसाब से रंगा होता है। रंग बताता है कि कहाँ ज़्यादा या कम है, क्यों नहीं।'],['ट्रेंड, रेज़िडुअल, z-स्कोर','ट्रेंड लंबे समय की दिशा है। रेज़िडुअल यानी कोई साल उस दिशा से कितना हटा। z-स्कोर इसे सामान्य अंतर से भाग देता है; 2 से ऊपर असामान्य माना जाता है।'],['सहसंबंध (r)','−1 से 1 के बीच। बताता है कि दो चीज़ें साथ चलती हैं या नहीं, यह नहीं कि एक दूसरी का कारण है।'],['सीएजीआर','चक्रवृद्धि वार्षिक वृद्धि दर: वह स्थिर सालाना प्रतिशत जो मान को शुरू से अंत तक पहुँचाए।'],['अगहनी, भदई, गर्मा, रबी','बिहार के ज़िला रिकॉर्ड चार मौसम गिनते हैं: अगहनी मुख्य ख़रीफ़ (जाड़े का धान), भदई शुरुआती ख़रीफ़, गर्मा गर्मी का मौसम और रबी सर्दियों में बोया मौसम।'],['प्रभावी फ़सल संख्या','फ़सल-विविधता का माप: कितनी बराबर आकार की फ़सलें यही मिश्रण देंगी। ज़्यादा यानी ज़्यादा फैली हुई खेती।'],['लोकेशन कोशिएंट','ज़िले में किसी फ़सल का हिस्सा ÷ राज्य में उसका हिस्सा। 1 से ऊपर यानी ज़िला उस फ़सल में विशेषज्ञ है।'],['उपज अंतर','ज़िले की उपज लक्ष्य (जैसे राज्य औसत) से कितनी कम है, उसे क्षेत्रफल से गुणा करके टन में।'],['संरचनात्मक मोड़','वह साल जिसके बाद रुझान की रफ़्तार बदलती है, दो सीधी रेखाएँ बैठाकर पाया जाता है। यह बदलाव बताता है, कारण नहीं।'],['k-मीन्स समूह','मिलती-जुलती फ़सलों वाले ज़िलों को एक साथ रखने का तरीक़ा। समूह चुनी हुई संख्या पर निर्भर करते हैं।']];
const tr=s=>LANG=='hi'&&HI[s]?HI[s]:s;
function buildNav(){$('nav').innerHTML=PG.map(p=>`<button data-go="${p[0]}" class="${p[0]==page?'on':''}">${tr(p[1])}</button>`).join('')}
function buildSeg(){$('modeseg').innerHTML=MODES.map((m,i)=>{const h=LANG=='hi'?HIM[i]:m;return`<button data-mode="${i}" class="${i==mode?'on':''}" title="${h[0]}: ${h[2]}">${h[1]}</button>`}).join('')}
function modeLine(){const m=LANG=='hi'?HIM[mode]:MODES[mode];$('modeline').innerHTML=LANG=='hi'?`आप <b>${m[0]}</b> के रूप में पढ़ रहे हैं · ${m[2]} सामग्री, व्याख्याएँ और AI उत्तर इस दृष्टि से बदलते हैं।`:`Reading as <b>${m[0]}</b> · ${m[2]} Content, explanations and AI answers change with this mode.`}
