function rStories(){const C=curated();$('stories').innerHTML=head('Data Stories','Questions, evidence and what is still unknown','Curated stories that put the numbers next to real articles and reports, and a generator that builds a story from your own filters.')+guide('stories')+
`<div class="c" style="margin-top:14px;border-color:var(--ac)"><div class="k">Story generator</div><h3>Build a story from your own filters</h3><p class="sub sm" style="margin-bottom:10px">Choose where, which crop and what to focus on. The platform computes the facts, matches sourced articles and writes the story for your reading mode (${MODES[mode][0]}).</p>
<div class="bar" style="margin:0 0 8px"><select id="gg" aria-label="Place"><option value="-1">Bihar (statewide, 1966–2024)</option>${NM.map((n,i)=>`<option value="${i}">${n} district (2024–25)</option>`).join('')}</select><select id="gc" aria-label="Crop"></select><select id="gl" aria-label="Focus"><option value="change">What changed</option><option value="compare">How it compares</option><option value="why">What might explain it</option></select></div><div class="bar" style="margin:0 0 10px" id="gper"><span class="sm m">From</span><select id="gf">${YR.map(y=>`<option value="${y}">${fy(y)}</option>`).join('')}</select><span class="sm m">to</span><select id="gt">${YR.map(y=>`<option value="${y}"${y==2024?' selected':''}>${fy(y)}</option>`).join('')}</select><button class="btn" id="ggo">Generate story</button></div><div id="gout"></div></div>
<h2>Curated stories</h2>`+C.map((s,i)=>`<div class="c" style="margin-bottom:18px"><div class="k">Story 0${i+1} · ${s.k}</div><h3 style="font-size:26px;line-height:1.2">${s.t}</h3><p class="sub">${s.d}</p><div class="ov">${s.viz}</div><div class="take"><div class="k">What the data show</div>${s.obs}</div><div class="take" style="border-color:var(--ac)"><div class="k">Reading for ${MODES[mode][0]}</div>${s.lens[mode]}</div><h3 style="margin-top:14px">What reports say</h3>${evPick(s.ev)}<div class="take w2"><div class="k">Still unknown</div>${s.unk}</div><button class="btn o" data-sai="${i}">Ask the AI to write this story up</button><div class="aib" id="sai${i}" style="margin-top:10px"></div></div>`).join('');
const setC=()=>{const g=+$('gg').value;$('gc').innerHTML=g<0?optgH('Rice'):optg('Rice');$('gper').querySelectorAll('select').forEach(x=>x.disabled=g>=0)};setC();$('gg').onchange=setC;$('ggo').onclick=genStory;
$('stories').onclick=e=>{const b=e.target.closest('[data-sai]');if(!b)return;const i=+b.dataset.sai,s=C[i],ev=s.ev.map(id=>({e:EV.find(x=>x.id==id),d:1})),rows=[['Story',s.t],['What the data show',s.obs.replace(/<[^>]+>/g,'')]];runAI($('sai'+i),b,{kind:'story',mode:BADGE[mode],lang:aiLang,title:s.t,rows,evidence:ev.map(x=>({title:x.e.ti,source:x.e.so,url:x.e.u,gist:x.e.g})),entities:{place:'Bihar'},prompt:buildPrompt('Write a short, clear data story from this evidence',s.t,rows,ev,mode,aiLang)})}}
function genStory(){const g=+$('gg').value,c=$('gc').value,lens=$('gl').value;let T,body='',rows=[],ev=[],viz='',ent={};
if(g<0){let f=I(+$('gf').value),t=I(+$('gt').value);if(f>=t){$('gout').innerHTML='<p class="sm" style="color:var(--wn)">Choose a start year before the end year.</p>';return}const v=D[c].Y,sl=v.map((x,i)=>i>=f&&i<=t?x:null),ok=sl.map((x,i)=>x==null?null:i).filter(i=>i!=null);if(ok.length<4){$('gout').innerHTML='<p class="sm m">Not enough data for this crop in that period.</p>';return}
 const s0=ok[0],s1=ok[ok.length-1],a=v[s0],b=v[s1],cg=Math.pow(b/a,1/(s1-s0))-1,pk=ok.reduce((x,i)=>v[i]>v[x]?i:x,ok[0]),tr=ok.reduce((x,i)=>v[i]<v[x]?i:x,ok[0]),falls=ok.filter(i=>i>s0&&v[i-1]!=null&&v[i]/v[i-1]-1<-.1).map(i=>[i,v[i]/v[i-1]-1]).sort((x,y)=>x[1]-y[1]).slice(0,3),N=D[c].N,nr0=N[s0]?a/N[s0]:null,nr1=N[s1]?b/N[s1]:null,hist=falls.map(x=>histM(c,'Y',x[0]));
 T=`${c} yield in Bihar, ${fy(1966+s0)} to ${fy(1966+s1)}: ${(b/a).toFixed(1)}× ${b>=a?'higher':'lower'}`;
 rows=[['Place','Bihar statewide'],['Crop',c],['Period',`${fy(1966+s0)} to ${fy(1966+s1)}`],['Yield start → end',`${fmt(a)} → ${fmt(b)} kg/ha`],['Compound growth a year',pc(cg)],['Highest year',`${fy(1966+pk)} (${fmt(v[pk])})`],['Lowest year',`${fy(1966+tr)} (${fmt(v[tr])})`],['Falls above 10%',falls.length?falls.map(x=>`${fy(1966+x[0])} ${pc(x[1])}`).join(', '):'none'],['Bihar ÷ India yield, start → end',nr0&&nr1?`${(nr0*100).toFixed(0)}% → ${(nr1*100).toFixed(0)}%`:'n/a']];
 const fl=falls.map(x=>`<b>${fy(1966+x[0])}</b> (${pc(x[1])})`).join(', ');
 if(mode==0)body=`<p>Between ${fy(1966+s0)} and ${fy(1966+s1)}, each hectare of ${c.toLowerCase()} in Bihar went from giving ${fmt(a)} kg to ${fmt(b)} kg, about ${(b/a).toFixed(1)} times as much.</p><p>${falls.length?`The roughest years were ${fl}. Those are worth clicking on the chart below.`:'There was no single year with a fall of more than 10%.'}</p>${lens=='compare'&&nr1?`<p>Compared with India, Bihar’s ${c.toLowerCase()} yield went from ${(nr0*100).toFixed(0)}% of the India average to ${(nr1*100).toFixed(0)}%.</p>`:''}<p class="m">Numbers describe what happened, not why. The articles below are the documented context; everything else is a question to ask locally.</p>`;
 if(mode==1)body=tbl(rows)+`<div class="take w2 sm"><b>Method.</b> Series from the DA&amp;FW statewide workbook, season Total. CAGR over the selected window; falls are year-on-year changes below −10%. The latest year is an advance estimate. Open any fall for its trend z-score and decomposition.</div>`;
 if(mode==2)body=`<ul class="sm"><li><b>Growth:</b> ${pc(cg)} a year, ${fy(1966+s0)}–${fy(1966+s1)}.</li><li><b>Volatility:</b> ${falls.length} year(s) with a fall above 10%${falls.length?': '+fl:''}.</li>${nr1?`<li><b>Gap to India:</b> Bihar is at ${(nr1*100).toFixed(0)}% of the India yield at the end of the window${nr0?` (from ${(nr0*100).toFixed(0)}%)`:''}.</li>`:''}</ul><div class="take sm"><b>Decision questions.</b> Are falls recurring shocks that call for risk cover or irrigation support, or one-offs? Is the gap to India narrowing? Which districts drove the dips (not answerable with statewide data)?</div>`;
 const fy_=falls.map(x=>x[0]);hist.forEach(h=>{if(h)ev.push(...evFor({c,y:h.y,t:h.rain!=null&&h.rain<h.rm*.85?'drought':null}))});if(!ev.length)ev=evFor({c});const seen={};ev=ev.filter(x=>seen[x.e.id]?0:(seen[x.e.id]=1)).slice(0,4);
 viz=lineChart({S:[{n:c,v:sl,c:'var(--nv)'},...(N.some(x=>x!=null)?[{n:'India',v:sl.map((x,i)=>x==null?null:N[i]),c:'var(--gr)',d:1}]:[])],unit:'Yield (kg/ha)',flag:fy_,pk:i=>`hist|${c}|Y|${i}`});ent={crop:c,place:'Bihar',year:`${fy(1966+s0)} to ${fy(1966+s1)}`}}
else{const dm=distM(c,'P',g),da=distM(c,'A',g),dy=distM(c,'Y',g);T=`${NM[g]}: ${c} in 2024–25`;rows=[...rowsDist(dm),['Rank by area / production / yield',`${da.rank||'n/r'} / ${dm.rank||'n/r'} / ${dy.rank||'n/r'} of ${dm.n}`]];
 if(mode==0)body=distNarr(dm,0)+`<p>Rankings: area ${da.rank||'not reported'}, harvest ${dm.rank||'not reported'}, harvest per hectare ${dy.rank||'not reported'} (out of ${dm.n} districts that report it).</p>`;if(mode==1)body=distNarr(dm,1)+`<p class="sm">Ranks by area / production / yield: ${da.rank||'n/r'} / ${dm.rank||'n/r'} / ${dy.rank||'n/r'}.</p>`;if(mode==2)body=distNarr(dm,2);
 ev=evFor({c,p:NM[g]});viz=`<div style="max-width:520px;margin:0 auto">${mapSVG(c,'P',true,g).svg}</div>`;ent={crop:c,place:NM[g]+' district',year:'2024–25'}}
$('gout').innerHTML=`<div class="take" style="border-color:var(--ac);margin-top:14px"><div class="k">Generated for ${MODES[mode][0]}</div><h3 style="font-size:24px">${esc(T)}</h3></div><div class="ov">${viz}</div>${body}<h3 style="margin-top:14px">Matching articles and reports</h3>${evHTML(ev)}<button class="btn o" id="gai">Ask the AI to write this up</button><div class="aib" id="gaib" style="margin-top:10px"></div>`;
$('gai').onclick=e=>runAI($('gaib'),e.target,{kind:'story',mode:BADGE[mode],lang:aiLang,title:T,rows,evidence:ev.map(x=>({title:x.e.ti,source:x.e.so,url:x.e.u,gist:x.e.g})),entities:ent,prompt:buildPrompt(`Write a short data story for the "${$('gl').value}" focus`,T,rows,ev,mode,aiLang)})}
