function offNote(c,m){if(!BO[c])return'';const o=BO[c][m],ser=D[c][m],g=o[4]/ser[58]-1,yo=o[4]/o[3]-1,ys=ser[58]/ser[57]-1,flip=(yo>0)!=(ys>0)&&Math.abs(yo)>.005&&Math.abs(ys)>.005;
return BM(`<div class="take" style="border-color:var(--ac)"><div class="k">Bihar’s own figures</div>The gold diamonds are Bihar’s official records for 2020–21 to 2024–25. For ${fy(2024)}, Bihar’s record says ${ML2[m]} was <b>${fmt(o[4])} ${UN[m]}</b>, against ${fmt(ser[58])} in the statewide series (${pc(g)}). ${flip?`The two even disagree on direction last year: ${pc(yo)} in Bihar’s record, ${pc(ys)} in the series. `:''}Bihar’s figure is the one to trust for Bihar. <button class="lk" data-offc="${c}">See the full comparison →</button></div>`,
`<div class="take w2 sm"><b>Source check.</b> ${fy(2024)} ${ML2[m]}: Bihar official ${fmt(o[4])} vs DA&amp;FW series ${fmt(ser[58])} (${pc(g)}); year on year ${pc(yo)} vs ${pc(ys)}. The statewide series equals the national file for Bihar and its latest year is an advance estimate; Bihar’s record governs from 2020–21. <button class="lk" data-offc="${c}">Open the comparison →</button></div>`,
`<div class="take sm"><b>Plan with Bihar’s number.</b> ${fy(2024)} ${ML2[m]}: ${fmt(o[4])} ${UN[m]} (Bihar) vs ${fmt(ser[58])} (statewide series), a ${pc(g)} gap. ${flip?'The sources disagree on the direction of change, so growth conclusions depend on which is used. ':''}<button class="lk" data-offc="${c}">Compare sources →</button></div>`)}
