function dust(){cancelAnimationFrame(raf);const c=$('dust'),x=c.getContext('2d');if(!x)return;let W=c.width=innerWidth,H=c.height=innerHeight;const P=Array.from({length:70},()=>({x:Math.random()*W,y:Math.random()*H,r:Math.random()*1.6+.3,v:Math.random()*.35+.08,a:Math.random()*.6+.2}));const f=()=>{if(!c.isConnected)return;x.clearRect(0,0,W,H);P.forEach(p=>{p.y-=p.v;p.x+=Math.sin(p.y/60)*.15;if(p.y<-5){p.y=H+5;p.x=Math.random()*W}x.beginPath();x.arc(p.x,p.y,p.r,0,7);x.fillStyle='rgba(233,185,73,'+p.a+')';x.fill()});raf=requestAnimationFrame(f)};f()}
function buildIntro(){const v=dvals('Rice','P'),s=v.filter(x=>x!=null).sort((a,b)=>a-b),br=[.2,.4,.6,.8].map(q=>s[Math.floor(q*(s.length-1))]),H=['#1d4030','#2f6a42','#55933f','#9bc65c','#ecc65a'];
INT.className='intro';INT.innerHTML=`<canvas id="dust"></canvas><button class="skip" id="skip">Skip intro →</button><div class="il"><p class="l1">Sixty years of harvests.</p><p class="l2">Thirty-eight districts.</p><p class="l3">One question: what changed?</p></div><div class="im"><svg viewBox="-8 -8 716 ${M.h+16}" aria-hidden="true">${M.d.map((d,i)=>`<path class="ip" pathLength="1" style="--d:${Math.round(+d[1].match(/M(\d+)/)[1]/24)};--fc:${v[i]==null?'#1c3a2c':H[br.filter(b=>v[i]>b).length]}" d="${d[1]}"/>`).join('')}</svg></div><div class="brandi"><img alt="AgriBihar" src="${$('fld').src}"><button class="btn en" id="enter">Enter AgriBihar</button></div>`;$('skip').onclick=$('enter').onclick=enter;dust()}
function enter(){INT.classList.add('out');cancelAnimationFrame(raf);try{sessionStorage.setItem('abi','1')}catch(e){}setTimeout(()=>INT.classList.add('hide'),950);countUp()}
document.addEventListener('keydown',e=>{if((e.key=='Escape'||e.key=='Enter')&&INT.classList.contains('intro')&&!INT.classList.contains('hide')&&!INT.classList.contains('out')&&!e.target.matches?.('[data-p]'))enter()});
$('replay').onclick=()=>{go('overview');buildIntro()};$('logo').onclick=()=>go('overview');
$('tg').onclick=()=>{const n=document.documentElement.dataset.theme=='dark'?'light':'dark';document.documentElement.dataset.theme=n;try{localStorage.setItem('abt',n)}catch(e){}};
let seen=false;try{seen=sessionStorage.getItem('abi')=='1'}catch(e){}
buildNav();$('lang').textContent=LANG=='hi'?'EN':'हि';aiLang=LANG;const hh=location.hash.length>1;setMode(0);go('overview');if(hh){try{applyCode(location.hash)}catch(e){}INT.className='intro hide'}else if(seen){INT.className='intro hide'}else buildIntro();decorate();


